  "decline_reason": "",
  "claims": [
    {
      "text": "Yes—under the Manual’s practice, suspension for settlement negotiations is available in certain circumstances once the two six-month cooling-off provisions have been fully utilised, following filing of the notice of intention to oppose and supporting statement of grounds and particulars.",
      "quotes": [
        {
          "ref": "TMM/Part51/4/4/1~1",
          "quote": "Suspension of the opposition proceedings is available (in certain circumstances) once the option of the (two 6 month) cooling-off provisions has been fully utilised, following the filing of a Notice of Intention to Oppose and a supporting Statement of Grounds and Particulars."
        },
        {
          "ref": "TMM/Part51/4/4/1~1",
          "quote": "A direction may be made for the evidence stage of opposition proceedings to be temporarily suspended in order to give the parties the opportunity to conduct settlement negotiations without the need to apply and pay for successive extensions of the period within which to file evidence."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For that settlement-negotiation suspension, both sides must agree: the request must be made jointly or accompanied by the other side’s written consent.",
      "quotes": [
        {
          "ref": "TMM/Part51/4/4/1~1",
          "quote": "The Registrar will only suspend proceedings if the request is made by both parties or if the party requesting suspension provides the written consent of the other side."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The parties may request an initial suspension of up to six months, or one year in exceptional circumstances.",
      "quotes": [
        {
          "ref": "TMM/Part51/4/4/1~1",
          "quote": "The parties may request the Registrar to suspend proceedings for an initial period of up to six months and in exceptional circumstances one year."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Continuation of the initial suspension depends on the Registrar being satisfied that negotiations have progressed sufficiently to establish a real likelihood of settlement, assessed case by case.",
      "quotes": [
        {
          "ref": "TMM/Part51/4/4/1~1",
          "quote": "The initial suspension may be continued provided the Registrar is satisfied negotiations have progressed such that there is a real likelihood of settlement. That will be determined on a case by case basis."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "There is no fee for requesting suspension.",
      "quotes": [
        {
          "ref": "TMM/Part51/4/4/1~1",
          "quote": "There is no fee for requesting suspension."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The agreement requirement for settlement suspension should not be generalised to every suspension: the Manual separately records that the Registrar may suspend an opposition timetable on request or at her discretion pending completion of a related matter that may affect the substantive opposition.",
      "quotes": [
        {
          "ref": "TMM/Part51/4/4/3",
          "quote": "The Registrar may on request or at Her discretion suspend the timetable of an opposition pending the completion of a related matter that may impact on the outcome of the substantive opposition."
        },
        {
          "ref": "TMM/Part51/4/4/3",
          "quote": "Each request or circumstance will be decided on its merits and on a case by case basis and if appropriate the parties given an opportunity to make representations on a proposed direction in accordance with the relevant provisions of the Trade Marks Regulations 1995."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The supplied passages establish the Manual’s practice, not the complete legislative requirements: the relevant suspension regulations are identified in the Manual but their text is not supplied, so I cannot independently confirm their full conditions or exceptions here.",
      "quotes": [],
      "authority": "none"
    }
  ],
